import {cityPanel,sciencePanel,speciesPanel,progressionPanel,upgradeView} from './civilization-ui.js';
import {realismReady,realismThumbnail} from './realism-assets.js';
import {EARLY,earlyThumbnail} from './horizons-art.js';
import * as G from './horizons.js';
import {HorizonsRenderer} from './horizons-render.js';
import {thumbnail,artReady} from './world.js';
import {loadWorld,persistWorld,emergencyMirror} from './world-storage.js';
const $=q=>document.querySelector(q),$$=q=>document.querySelectorAll(q),esc=t=>String(t).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),fmt=n=>Math.floor(n).toLocaleString('es-CO'),time=n=>n>=3600?(n/3600).toFixed(1)+' h':Math.ceil(Math.max(0,n)/60)+' min';
const symbols={water:'≈',copper:'◈',tin:'⬡',salt:'◇',silica:'⬡',lithium:'◇',titanium:'◆',uranium:'☼',iridium:'✦',aether:'✧',wood:'♧',stone:'⬡',food:'❦',iron:'▰',coal:'◆',gold:'◇',oil:'◒',crystal:'✧',credits:'◈'};
let state,loadError=null;try{const raw=await loadWorld();state=raw?G.deserialize(raw):G.createSurvival();}catch(e){loadError=e;state=G.createSurvival();}
let selected=G.units(state).slice(0,1).map(u=>u.id),tab='base',tool=null,mode='select',formation='line',layer=0,hover=null,box=null,groups={},installPrompt=null,pendingImport=null,routeTo='',routeResource='wood',routeKind='ship',lastSave=-1,toastTimer,dirty=true,roadPoints=[],roadGrade='trail',roadPreview=null,recruitSpecies='human';
const renderer=new HorizonsRenderer($('#game'));renderer.map=G.currentMap(state);
function center(){const m=G.currentMap(state),u=m.units.find(u=>selected.includes(u.id)&&u.hp>0&&!u.embarked)||m.units.find(u=>u.hp>0&&!u.embarked)||m.buildings.find(b=>b.type==='camp')||{x:m.size/2,y:m.size/2};renderer.centerOn(u.x,u.y);}
center();
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4200);}
async function save(){if(loadError)return;try{const raw=G.serialize(state);await persistWorld(raw);$('#save-status').textContent='GUARDADO LOCAL';lastSave=state.time;}catch{$('#save-status').textContent='EXPORTA UNA COPIA';}}
function act(result){if(result.message)toast(result.message);dirty=true;if(result.ok){save();render();}return result;}
function costs(cost){const m=G.currentMap(state);return '<div class="cost">'+Object.entries(cost).map(([k,v])=>`<span class="${m.stock[k]<v?'missing':''}">${symbols[k]} ${v} ${G.STOCK_NAMES[k]}</span>`).join('')+'</div>';}
function thumb(type,unit=false,tier=state.era){return `<canvas data-art="${type}" data-tier="${tier}" ${unit?'data-unit="true"':''}></canvas>`;}
function drawArt(){for(const c of document.querySelectorAll('canvas[data-art]')){const type=c.dataset.art,unit=c.dataset.unit==='true',tier=Number(c.dataset.tier??state.era);if(unit&&type==='settler'&&tier>=17){thumbnail(c,'ranger',true);continue;}if(realismThumbnail(c,type,unit,tier))continue;else if(!unit&&tier<12&&EARLY.has(type)||unit&&['settler','raft','galley'].includes(type))earlyThumbnail(c,type,unit);else thumbnail(c,unit?(G.TROOPS[type]?.art||type):(G.STRUCTURES[type]?.art||type),unit);}}
function panelHead(kicker,title,lead){return `<div class="panel-head"><div><div class="eyebrow">${kicker}</div><h2>${title}</h2></div><button data-action="close-panel" aria-label="Cerrar panel">×</button></div><p>${lead}</p>`;}
function modal(html){$('#modal-body').innerHTML=html;if(!$('#modal').open)$('#modal').showModal();drawArt();}
function modalHead(title){return `<div class="panel-head"><h2>${title}</h2><button data-action="close-modal" aria-label="Cerrar">×</button></div>`;}
function chooseTab(next){tab=next;tool=null;roadPoints=[];roadPreview=null;$('#panel').hidden=tab==='base';$$('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));render();}
function setTool(next){tool=next;chooseTab('base');tool=next;render();}
function renderResources(){const m=G.currentMap(state);$('#resources').innerHTML=['wood','stone','food','water','iron','credits'].map(k=>`<div class="stock" title="${G.STOCK_NAMES[k]} disponibles en ${esc(m.name)}"><i>${symbols[k]}</i><span><small>${G.STOCK_NAMES[k].toUpperCase()}</small>${fmt(m.stock[k])}</span></div>`).join('');$('#world-title').textContent=layer?'Bajo la superficie.':m.name;$('#world-kicker').textContent=layer?'EXCAVACIÓN · CAPA '+layer+' DE 40':m.kind==='ocean'?'NAVEGACIÓN · TIERRA POR DESCUBRIR':G.ERAS[state.era].domain.toUpperCase()+' · DIFICULTAD MÁXIMA';const c=G.clock(state);$('#world-info').textContent='Día '+c.day+' · '+(c.night?'Noche':'Día')+' · '+c.label+' · '+G.ERAS[state.era].name+' · nivel '+state.ageLevel+'/10';const status=$('#vital-status');status.textContent='Pueblo · Agua '+fmt(m.stock.water)+' · Bienestar '+Math.round(m.city.happiness)+'% · '+(state.ethics.score>=0?'+':'')+state.ethics.score.toFixed(0)+' moralidad'+(state.dilemmas.some(d=>!d.resolved)?' · Decisión pendiente':'');const event=state.events.find(e=>e.map===m.id);$('#alert').hidden=!event;if(event)$('#alert').textContent=G.HAZARDS[event.type].name+' · '+(event.starts>state.time?'Zona señalada: evacúa en '+Math.ceil(event.starts-state.time)+' s.':'Evento activo. Mantén las unidades a salvo.');}
function renderSidebar(){const m=G.currentMap(state),u=m.units.find(u=>selected.includes(u.id)),building=m.buildings.find(b=>selected.includes(b.id)),spec=building?G.STRUCTURES[building.type]:u?G.TROOPS[u.type]:null;let html='<div class="eyebrow">'+(building?'INFRAESTRUCTURA':u?'UNIDAD SELECCIONADA':'DIARIO DE AURORA')+'</div>';
 if(spec){html+='<div class="side-art">'+thumb(building?building.type:u.type,!!u,building?.tier??u?.technology??state.era)+'</div><span class="tag">'+(u?spec.civilian?'EXPLORAR · RECOLECTAR · CONSTRUIR':spec.naval?'ARMADA':spec.flying?'AVIACIÓN':'EJÉRCITO':'CIVILIZACIÓN')+'</span><h2>'+spec.name+'</h2><p>'+(building?spec.description:u?spec.civilian?'Tu civilización empieza con sus manos. La niebla se retira al explorar. Recolecta los nodos del terreno y despeja espacios para construir.':'Las bajas son permanentes. Cuida sus alimentos y prepara caminos para llegar más lejos.':'')+'</p>';
 html+=`<div class="side-line"><span>Integridad</span><strong>${Math.ceil((u||building).hp)} / ${u?u.maxHp:G.buildingStats(building,spec).hp}</strong></div>`;if(u){const labels={hold:'En espera',move:'En marcha',attackMove:'Avanzar y atacar',gather:'Recolectando',explore:'Explorando',dig:'Excavando',construct:'Construyendo',attack:'Atacando'};html+=`<div class="side-line"><span>Orden</span><strong>${labels[u.order.kind]||'En espera'}${u.order.blocked?' · ruta bloqueada':''}</strong></div><div class="side-line"><span>Posición</span><strong>${Math.floor(u.x)}, ${Math.floor(u.y)} · capa ${u.depth}</strong></div><div class="side-line"><span>Órdenes en cola</span><strong>${u.queue.length} / 32</strong></div>`;if(u.provisions)html+='<div class="side-line"><span>Provisiones de la flota</span><strong>'+fmt(u.provisions.food)+' alimentos · '+fmt(u.provisions.water)+' agua</strong></div>';if(u.embarked)html+='<p class="warning">A bordo de un transporte. Selecciona el barco para navegar.</p>';if(u.order.kind==='dig')html+='<div class="progress"><i style="width:'+u.order.work/u.order.duration*100+'%"></i></div>';}if(building&&building.progress<1)html+='<p class="warning">En construcción · '+Math.floor(building.progress*100)+'%</p><button data-action="resume-build" data-id="'+building.id+'">Asignar colono cercano</button>';}
 else html+='<h2>Un mundo por fundar.</h2><p>Todo comienza con un colono y los inventarios vacíos. Cada recurso, cada camino y cada nueva era habrá que ganarlos.</p>';
 if(building&&building.progress>=1)html+='<button class="primary full" data-action="inspect-upgrade" data-id="'+building.id+'">INFORMACIÓN Y MEJORAS · NIVEL '+building.level+'/10</button>';if(u)html+='<div class="side-line"><span>Pueblo</span><strong>'+G.SPECIES[u.species].name+'</strong></div><button class="full" data-tab="city">Gestionar trabajo y suministros</button>';html+='<div class="side-divider"></div><div class="eyebrow">LOS PRIMEROS PASOS</div>'+[{done:m.stock.wood>=50,text:'Reúne madera',sub:'Árboles y troncos · 50 para el campamento'},{done:m.stock.stone>=30,text:'Recoge piedra',sub:'Rocas de superficie · 30 para el campamento'},{done:m.stock.food>=20,text:'Busca alimentos',sub:'Arbustos de bayas · 20 para fundar'},{done:m.buildings.some(b=>b.type==='camp'&&b.progress>=1),text:'Funda tu primera población',sub:'Construye cerca de un colono, sobre terreno despejado'}].map(o=>'<div class="objective"><span>'+(o.done?'✓':'○')+'</span><div>'+o.text+'<small>'+o.sub+'</small></div></div>').join('');
 html+=`<div class="side-line"><span>Población</span><strong>${G.population(m)} / ${G.capacity(m)}</strong></div><div class="side-line"><span>Bajas definitivas</span><strong>${m.casualties}</strong></div><button class="primary full" data-tab="era">DESARROLLAR LA CIVILIZACIÓN →</button><div class="side-divider"></div><div class="eyebrow">ÚLTIMOS SUCESOS</div>`+state.news.slice(0,4).map(n=>'<div class="news">'+esc(n.message)+'<small>Día '+(Math.floor(n.time/1200)+1)+' · '+Math.floor(n.time/60)+' min de campaña</small></div>').join('');$('#sidebar').innerHTML=html;
}
function renderDock(){const m=G.currentMap(state);$('#dock').innerHTML='<span class="build-label">CONSTRUIR CIVILIZACIÓN</span>'+Object.entries(G.STRUCTURES).map(([type,spec])=>{const locked=state.era<spec.era;return `<button class="build-card ${tool===type?'active':''} ${locked?'locked':''}" data-action="build-tool" data-type="${type}" title="${esc(spec.description)}"><small>${locked?'ERA '+(spec.era+1)+' · '+G.ERAS[spec.era].name.toUpperCase():time(spec.time)+' DE TRABAJO'}</small>${thumb(type)}<strong>${spec.name}</strong><small>${Object.entries(spec.cost).map(([k,v])=>symbols[k]+' '+v).join(' · ')}</small></button>`;}).join('');
 $('#commands').innerHTML='<strong>'+m.units.filter(u=>selected.includes(u.id)&&u.hp>0).length+' seleccionadas</strong>'+[['select','Seleccionar'],['move','Mover'],['attackMove','Avanzar + atacar'],['hold','Detener'],['explore','Explorar'],['gather','Recolectar'],['embark','Embarcar'],['unload','Desembarcar']].map(([kind,label])=>`<button data-action="command" data-type="${kind}" class="${mode===kind?'active':''}">${label}</button>`).join('')+'<button data-action="supply-load">Cargar provisiones</button><button data-action="supply-unload">Desembarcar suministros</button><button data-action="all">Todas</button><button data-action="formation">'+(formation==='line'?'Línea':'Columna')+'</button>';
 $('#tool-banner').hidden=!tool;if(tool?.startsWith('road-')){$('#tool-banner').innerHTML='TRAZADO · '+G.ROAD_GRADES[roadGrade].name+' · <span id="road-price">'+(tool==='road-curve'?'Marca inicio, control y final.':'Marca inicio y final, o arrastra el tramo.')+'</span><button data-action="cancel-tool">×</button>';return;}if(tool)$('#tool-banner').innerHTML=esc(G.STRUCTURES[tool]?.name||({dig:'Excavar bloque',support:'Colocar entibado',stairs:'Colocar escalera',wall:'Colocar muralla',path:'Trazar camino',bridge:'Construir puente',rail:'Tender vía férrea',pipe:'Tender tubería',raise:'Elevar terreno'}[tool]||tool))+' · Capa '+layer+' · Toca el terreno cerca de un colono <button data-action="cancel-tool">×</button>';
}
function armyPanel(){const m=G.currentMap(state);return panelHead('POBLACIÓN Y EJÉRCITO','Cada unidad cuenta.','Recluta civiles, tropas históricas, vehículos, armada y aviación a medida que desarrollas las eras. Los soldados y barcos destruidos se pierden definitivamente.')+'<div class="toolbar"><label>Pueblo de los reclutas <select id="recruit-species" aria-label="Pueblo de los reclutas">'+state.species.map(k=>'<option value="'+k+'" '+(k===recruitSpecies?'selected':'')+'>'+G.SPECIES[k].name+'</option>').join('')+'</select></label><button data-tab="species">Descubrir nuevos pueblos</button></div><div class="cards">'+Object.entries(G.TROOPS).map(([type,u])=>{const locked=state.era<u.era,facility=m.buildings.some(b=>b.type===u.facility&&b.hp>0&&b.progress>=1);return `<article class="card">${thumb(type,true)}<span class="badge">${u.civilian?'CIVIL':u.naval?'ARMADA':u.flying?'AVIACIÓN':'EJÉRCITO'} · ERA ${u.era+1}</span><h3>${u.name}</h3><p>${u.hp} vida · ${u.damage} daño · ${u.range} alcance${u.carrier?' · '+u.carrier+' plazas':''}<br>${G.STRUCTURES[u.facility].name} · ${time(u.time)}</p>${costs(u.cost)}<button class="primary" data-action="recruit" data-type="${type}" ${locked||!facility||!G.canAfford(m,u.cost)?'disabled':''}>${locked?G.ERAS[u.era].name:!facility?'Construye '+G.STRUCTURES[u.facility].name:'Entrenar'}</button></article>`;}).join('')+'</div><h3 style="margin-top:24px">En preparación</h3>'+m.jobs.filter(j=>j.unit).map(j=>'<div class="side-line"><span>'+G.TROOPS[j.unit].name+'</span><strong>'+time(j.duration-j.elapsed)+'</strong></div>').join('');}
function eraPanel(){return progressionPanel(state);}
function worldPanel(){const m=G.currentMap(state),exits=m.exits.filter(e=>e.discovered),maps=Object.values(state.maps);return panelHead('EL MUNDO PERSISTENTE','Siempre hay otra costa.','Las islas y los océanos son mapas separados. Explora bajo la niebla, lleva un barco a una salida y navega hasta avistar tierra. Cada regreso conserva las construcciones, los recursos extraídos y las galerías. Antes de zarpar selecciona la flota y carga provisiones junto a un puerto. El agua y la comida viajan en sus bodegas; puedes desembarcarlas en una playa descubierta.')+`<div class="inventory"><div><small>TERRITORIOS VISITADOS</small><strong>${maps.length}</strong></div><div><small>MAPA ACTUAL</small><strong>${m.size}²</strong></div><div><small>SECTORES RESIDENTES</small><strong>${m.terrain.stats.resident} / ${m.terrain.stats.limit}</strong></div><div><small>MODIFICACIONES</small><strong>${fmt(m.terrain.stats.changed+Object.keys(m.voxels).length)}</strong></div></div><h3>${esc(m.name)} · ${m.kind==='ocean'?'Océano':G.BIOME_NAMES[m.biome]}</h3><p>Un bote costero puede volver al puerto de origen. Necesitas galeras o barcos posteriores para alcanzar otras tierras. Transporta colonos para poder fundar una colonia al desembarcar.</p><div class="exit-list">${exits.length?exits.map(e=>`<div class="exit-row"><span>${esc(e.name)}<small>${Math.floor(e.x)}, ${Math.floor(e.y)} · ${state.maps[e.destination]?esc(state.maps[e.destination].name):'Destino por explorar'}</small></span><button data-action="focus-exit" data-id="${e.id}">Localizar</button><button class="primary" data-action="travel" data-id="${e.id}">Navegar →</button></div>`).join(''):'<div class="empty">Todavía no has encontrado salidas. Recorre la isla hasta sus costas; en el océano, navega para avistar tierra.</div>'}</div><h3 style="margin-top:25px">Cartografía de la campaña</h3>`+maps.map(map=>'<div class="connection">'+(map.id===state.current?'● ':'○ ')+esc(map.name)+' · '+map.size+' × '+map.size+' · '+map.units.length+' unidades · '+map.buildings.length+' edificios'+map.exits.filter(e=>e.discovered&&state.maps[e.destination]).map(e=>'<small style="display:block;margin:5px 0 5px 17px">↔ '+esc(state.maps[e.destination].name)+'</small>').join('')+'</div>').join('');}
function peoplePanel(){const m=G.currentMap(state),factions=m.factions.filter(f=>f.discovered);return panelHead('COMERCIO, DIPLOMACIA Y GUERRA','No estás solo.','Las civilizaciones tienen reservas, tecnología y ejércitos propios. Las facciones hostiles envían incursiones; los aliados ofrecen suministros. Cumple encargos para ganar áureos y confianza.')+(factions.length?'<div class="cards">'+factions.map(f=>`<article class="card">${thumb(f.hostile?'barracks':'embassy')}<span class="badge">${f.owner==='player'?'CONQUISTADA':f.allied?'ALIADA':f.hostile?'HOSTIL':'NEUTRAL'} · ${G.ERAS[f.techEra??G.LEGACY_ERAS[f.era]].name}</span><h3>${esc(f.name)}</h3><p>Relación ${Math.floor(f.relation)} · Reserva ${fmt(f.wealth)}<br>Fortaleza ${Math.ceil(f.hp)} / ${f.maxHp}<br>Ayuda solicitada: ${f.offer.amount} ${G.STOCK_NAMES[f.offer.resource]}<br>Pago: ◈ ${f.offer.reward} áureos</p><button data-action="focus-faction" data-id="${f.id}">Localizar</button>${f.owner==='player'?(f.settlement?'<p>Ocupación: '+(f.settlement==='integrate'?'población integrada':'reservas saqueadas')+'</p>':'<button data-action="settle-conquest" data-type="integrate" data-id="'+f.id+'">Integrar · 120 alimentos + 100 agua · +10 moralidad</button><button data-action="settle-conquest" data-type="plunder" data-id="'+f.id+'">Saquear reservas · −20 moralidad</button>'):`<button data-action="diplomacy" data-id="${f.id}" data-type="trade">Cumplir encargo</button><button data-action="diplomacy" data-id="${f.id}" data-type="gift">Donar 50 alimentos</button><button data-action="diplomacy" data-id="${f.id}" data-type="alliance">Proponer alianza</button><button data-action="diplomacy" data-id="${f.id}" data-type="war">Declarar guerra</button>`}</article>`).join('')+'</div>':'<div class="empty">Explora para encontrar aldeas y bases enemigas. Su posición permanece oculta hasta que lleguen tus unidades.</div>')+'<h3 style="margin-top:24px">Inventario de '+esc(m.name)+'</h3><div class="inventory">'+Object.entries(m.stock).map(([k,v])=>'<div><small>'+G.STOCK_NAMES[k]+'</small><strong>'+symbols[k]+' '+fmt(v)+'</strong></div>').join('')+'</div><h3>Vender excedentes</h3><div class="toolbar">'+['wood','stone','iron','gold','oil','crystal'].map(k=>`<button data-action="sell" data-type="${k}">Vender 50 ${G.STOCK_NAMES[k]}</button>`).join('')+'</div>';}
function depthPanel(){return panelHead('40 CAPAS · TERRENO MODIFICABLE','La frontera también desciende.','Abre un pozo cerca del colono en la capa 1. Desciende por el pozo excavado y abre galerías laterales o continúa bajando. Puedes colocar bloques, escaleras y entibados; cada modificación es permanente.')+`<div class="card"><h3>Vista: ${layer?'capa '+layer:'superficie'}</h3><p>Era actual: profundidad máxima ${G.ERAS[state.era].depth}. A partir de la capa 3 necesitas una mina. Hierro, carbón, oro, cristal y petróleo dependen de la posición y la geología de la isla.</p><div class="toolbar"><button data-action="view-layer" data-depth="0">Superficie</button><input id="layer-range" type="range" min="0" max="40" value="${layer}" aria-label="Capa visible"><strong id="layer-label">${layer} / 40</strong><button data-action="descend">Llevar colonos a esta capa</button></div><div class="depth-scale">${Array.from({length:40},(_,i)=>`<button data-action="view-layer" data-depth="${i+1}" class="${layer===i+1?'active':''}">${i+1}</button>`).join('')}</div><div class="toolbar"><button class="primary" data-action="tool" data-type="dig">Excavar bloque</button><button data-action="tool" data-type="support">Colocar entibado</button><button data-action="tool" data-type="stairs">Colocar escalera</button><button data-action="tool" data-type="wall">Colocar bloque de piedra</button></div><p>Un colono debe estar a dos casillas de cada excavación. Los pozos se excavan en orden; cambiar la vista de capa no mueve a las unidades. El petróleo requiere refinería y tubería hasta el pozo. Los soportes reducen el daño de terremotos bajo tierra.</p></div>`;}
function routesPanel(){const m=G.currentMap(state),destinations=Object.values(state.maps).filter(map=>map.kind==='island'&&map.id!==m.id);if(!routeTo||!state.maps[routeTo])routeTo=destinations[0]?.id||'';return '<div class="road-planner"><span class="badge">TÚ DISEÑAS LOS CAMINOS</span><h3>Trazado de la ciudad</h3><p>Dos puntos para una recta; tres para una curva (inicio, control y final). También puedes arrastrar un tramo recto. La previsión muestra coste y obstáculos; un colono construye cada casilla. Los cruces se conectan y el trazado sobre agua requiere puentes.</p><div class="toolbar"><select id="road-grade" aria-label="Tipo de camino">'+Object.entries(G.ROAD_GRADES).map(([k,v])=>'<option value="'+k+'" '+(k===roadGrade?'selected':'')+'>'+v.name+'</option>').join('')+'</select><button class="primary" data-action="road-tool" data-type="straight">Trazar recta</button><button data-action="road-tool" data-type="curve">Trazar curva</button></div>'+m.roadWorks.map(j=>'<div class="side-line"><span>'+G.ROAD_GRADES[j.grade].name+' · '+j.index+' / '+j.steps.length+' casillas</span><div><button data-action="resume-civic" data-id="'+j.id+'">Asignar constructor</button><button data-action="cancel-road" data-id="'+j.id+'">Cancelar y devolver materiales pendientes</button></div></div>').join('')+'</div>'+panelHead('CAMINOS Y LÍNEAS DE SUMINISTRO','La distancia tiene un coste.','Construye infraestructura con colonos cercanos. Las rutas transportan existencias reales, consumen suministros y entregan la carga después del viaje. Los convoyes se ven en los mapas que recorren.')+'<div class="toolbar">'+[['path','Camino · 3 piedra'],['bridge','Puente · 18 madera + 8 piedra'],['rail','Vía · 8 hierro + 4 piedra'],['pipe','Tubería · 10 hierro'],['raise','Elevar · 8 piedra'],['wall','Muralla · 10 piedra']].map(([k,label])=>`<button data-action="tool" data-type="${k}">${label}</button>`).join('')+'</div><p>Los caminos aceleran el movimiento; los puentes permiten cruzar ríos; las vías deben unir físicamente la mina y el almacén. Las tuberías llevan petróleo desde el pozo hasta la refinería.</p><div class="card"><h3>Establecer una ruta entre islas</h3><div class="toolbar"><select id="route-to" aria-label="Destino de la ruta">'+destinations.map(map=>`<option value="${esc(map.id)}" ${map.id===routeTo?'selected':''}>${esc(map.name)}</option>`).join('')+'</select><select id="route-kind" aria-label="Transporte"><option value="ship" '+(routeKind==='ship'?'selected':'')+'>Barco · puertos + navegación</option><option value="air" '+(routeKind==='air'?'selected':'')+'>Avión · aeródromos + era moderna</option></select><select id="route-resource" aria-label="Recurso del convoy">'+Object.entries(G.STOCK_NAMES).map(([k,v])=>`<option value="${k}" ${k===routeResource?'selected':''}>${v}</option>`).join('')+'</select><button class="primary" data-action="create-route" '+(!destinations.length?'disabled':'')+'>Enviar 20 por viaje</button></div><p>'+(!destinations.length?'Primero descubre y coloniza otra isla.':'Se necesitan instalaciones operativas en ambos extremos.')+'</p><button data-action="rail-route">Activar tren entre mina y almacén</button><p>Las excavaciones profundas dejan sus materiales en la reserva minera cuando existe un almacén; el tren los lleva al inventario local.</p></div><div class="cards">'+state.routes.map(r=>`<article class="card"><span class="badge">${r.kind==='ship'?'CONVOY MARÍTIMO':r.kind==='air'?'CARGA AÉREA':'FERROCARRIL'}</span><h3>${esc(state.maps[r.from].name)} → ${esc(state.maps[r.to].name)}</h3><p>${r.amount} ${G.STOCK_NAMES[r.resource]} por viaje<br>${r.phase==='travel'?'En tránsito · '+time(r.duration-r.elapsed):'Esperando carga o suministros'}<br>Entregados: ${fmt(r.delivered)}</p><div class="progress"><i style="width:${r.phase==='travel'?r.elapsed/r.duration*100:0}%"></i></div></article>`).join('')+'</div>';}
function renderPanel(){if(tab==='base')return;const panel=$('#panel'),open=[...panel.querySelectorAll('details')].map(d=>d.open),scroll=panel.scrollTop;panel.innerHTML=({city:()=>cityPanel(state),science:()=>sciencePanel(state),species:()=>speciesPanel(state),army:armyPanel,era:eraPanel,world:worldPanel,people:peoplePanel,depth:depthPanel,routes:routesPanel}[tab]||worldPanel)();panel.querySelectorAll('details').forEach((d,i)=>d.open=!!open[i]);panel.scrollTop=scroll;}
function render(){renderResources();renderSidebar();renderDock();renderPanel();drawArt();dirty=false;}
function guide(){state.tutorialSeen=true;modal(modalHead('Toda civilización empieza así.')+'<div class="eyebrow">AURALIS FRONTIER · HORIZONTES</div><p>Empiezas sin recursos, moneda, edificios ni soldados. Solo tienes un colono. Gestiona comida y agua desde Pueblo; un manantial junto al punto de llegada permite recoger agua, y las granjas y pozos necesitan operarios asignados. Selecciónalo y toca los árboles, las rocas y los arbustos cercanos para recolectar.</p><p>Reúne <b>50 madera, 30 piedra y 20 alimentos</b>, elige Campamento en la barra inferior y colócalo en suelo descubierto y despejado, cerca del colono. El trabajador debe terminar la obra.</p><p>Arrastra con el botón central o activa ✥ para mover la cámara. En celular, arrastra con un dedo. Selecciona tropas con un clic o un recuadro; clic derecho ordena mover o atacar. <b>Shift encadena órdenes; Ctrl + 1–9 crea grupos; A avanza atacando; S detiene.</b></p><p>La niebla oculta el mundo. Desarrolla eras para construir barcos, navegar a océanos independientes y colonizar otras islas. En Subsuelo puedes excavar, descender y construir hasta 40 capas. Las bajas son permanentes y los desastres pueden ocurrir durante la partida.</p><p>Desarrolla 40 eras con diez niveles por era. Estudia minerales para aplicarlos a las mejoras. Maximizar los edificios permite un avance con descuento; adelantar la era consume enormes reservas. Los pactos y las decisiones de gobierno cambian tu moralidad y abren pueblos especiales. Traza tus propios caminos rectos y curvos en Suministros.</p><p>El juego se guarda en este dispositivo. Exporta copias para llevar tu mundo entre web, Android y Windows.</p><div class="actions"><button class="primary" data-action="close-modal">Comenzar a explorar →</button></div>');save();}
function settings(){modal(modalHead('Tu mundo, a salvo.')+'<p>Guardado local mediante IndexedDB. Solo el mapa activo se simula en detalle; las otras islas conservan su estado y avanzan de forma resumida mientras juegas.</p><div class="actions"><button data-action="export">Exportar mundo JSON</button><button data-action="import">Importar mundo</button><button data-action="downloads">Descargar / instalar</button><button data-action="guide">Guía de supervivencia</button></div><p>La campaña anterior conserva su propio guardado. <a href="./classic.html">Abrir campaña clásica →</a></p><p><a href="https://oscard0823.github.io/Pagina-Principal/">Ecosistema Auralis →</a></p><button data-action="reset-dialog">Nueva campaña de supervivencia</button><p class="tiny">Alpha 0.6 · Mundo por sectores de 32 × 32 · Islas de 2048 / 8192 casillas · Océanos de 8192 × 8192 · Vista estratégica isométrica con 40 capas de excavación. Las capas se muestran por separado.</p>');}
function downloads(){modal(modalHead('Lleva tu mundo contigo.')+'<p>Web instalable, Android y Windows. Exporta el mundo para trasladar la partida; el guardado no se sincroniza entre dispositivos.</p><a class="download" href="https://github.com/OscarD0823/auralis-frontier/releases/latest/download/Auralis-Frontier-Android.apk">Android · Descargar APK ↓</a><br><a class="download" href="https://github.com/OscarD0823/auralis-frontier/releases/latest/download/Auralis-Frontier-Windows-Setup.exe">Windows · Descargar instalador ↓</a><div class="actions"><button class="primary" data-action="install">Instalar versión web</button></div><p>'+ (installPrompt?'El navegador permite instalar esta aplicación.':'En Chrome o Edge: menú → Instalar aplicación. En Safari: Compartir → Añadir a pantalla de inicio. Abre una vez con conexión para descargar los archivos del juego.')+'</p>');}
async function exportWorld(){const data=G.serialize(state),filename='Auralis-Horizontes-'+new Date().toISOString().slice(0,10)+'.json';if(globalThis.Capacitor?.isNativePlatform?.()){try{const files=Capacitor.registerPlugin('Filesystem'),share=Capacitor.registerPlugin('Share'),result=await files.writeFile({path:filename,data,directory:'CACHE',encoding:'utf8'});await share.share({title:'Mundo de Auralis Frontier',files:[result.uri],dialogTitle:'Guardar partida'});}catch{toast('No se pudo compartir la copia. Intenta exportarla de nuevo.');}}else{const url=URL.createObjectURL(new Blob([data],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);}toast('Copia del mundo exportada.');}
document.addEventListener('click',async e=>{const nav=e.target.closest('[data-tab]');if(nav){chooseTab(nav.dataset.tab);return;}const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const a=b.dataset.action,type=b.dataset.type,id=b.dataset.id,m=G.currentMap(state);
 if(a==='close-modal'){$('#modal').close();return;}if(a==='close-panel'){chooseTab('base');return;}
 if(a==='supply-load'||a==='supply-unload'){act(G.provisionFleet(state,selected,a==='supply-unload'));return;}if(a==='inspect-upgrade'){modal(upgradeView(state,id));return;}if(a==='upgrade-confirm'){const r=act(G.upgradeBuilding(state,id));if(r.ok)$('#modal').close();return;}if(a==='study'){act(G.studyMaterial(state,type));return;}if(a==='resume-civic'){act(G.resumeCivic(state,id));if($('#modal').open)$('#modal').close();return;}if(a==='worker-task'){act(G.assignWorkers(state,[id],type));return;}if(a==='assign-selected'){act(G.assignWorkers(state,selected,$('#selected-work').value));return;}if(a==='focus-worker'){const u=m.units.find(v=>v.id===id);if(u){selected=[id];chooseTab('base');renderer.centerOn(u.x,u.y);}return;}if(a==='staff-building'){const u=m.units.find(u=>u.hp>0&&G.TROOPS[u.type].civilian&&!u.embarked&&u.depth===0&&!u.assignment&&u.order.kind==='hold');if(!u){toast('Libera o recluta un colono para asignarlo al edificio.');return;}act(G.assignWorkers(state,[u.id],type,id));return;}if(a==='policy'){act(G.setPolicy(state,id,type));return;}if(a==='unlock-species'){act(G.unlockSpecies(state,type));return;}if(a==='decision'){act(G.decide(state,id,type));return;}if(a==='settle-conquest'){act(G.settleConquest(state,id,type));return;}if(a==='cancel-road'){act(G.cancelRoad(state,id));return;}if(a==='road-tool'){roadGrade=$('#road-grade').value;setTool('road-'+type);roadPoints=[];roadPreview=null;return;}if(a==='settings')settings();else if(a==='guide')guide();else if(a==='downloads')downloads();else if(a==='center')center();else if(a==='zoom-in')renderer.camera.zoom=Math.min(2.5,renderer.camera.zoom+.15);else if(a==='zoom-out')renderer.camera.zoom=Math.max(.35,renderer.camera.zoom-.15);else if(a==='pan'){mode=mode==='pan'?'select':'pan';renderDock();}else if(a==='build-tool'){const spec=G.STRUCTURES[type];if(state.era<spec.era){toast('Desarrolla '+G.ERAS[spec.era].name+' para construir '+spec.name+'.');return;}if(layer){layer=0;renderer.layer=0;}setTool(type);}else if(a==='tool')setTool(type);else if(a==='cancel-tool'){tool=null;roadPoints=[];roadPreview=null;renderDock();}else if(a==='command'){tool=null;if(type==='hold')act(G.order(state,selected,'hold'));else if(type==='explore')act(G.order(state,selected,'explore'));else if(type==='embark'||type==='unload')act(G.board(state,selected,type==='unload'));else mode=type;renderDock();}else if(a==='all'){selected=m.units.filter(u=>u.hp>0&&!u.embarked&&u.depth===layer).map(u=>u.id);render();}else if(a==='formation'){formation=formation==='line'?'column':'line';renderDock();}else if(a==='resume-build')act(G.resumeBuild(state,id));else if(a==='recruit')act(G.recruit(state,type,recruitSpecies));else if(a==='research')act(G.researchEra(state,type));else if(a==='diplomacy')act(G.diplomacy(state,id,type));else if(a==='sell')act(G.marketSell(state,type));else if(a==='view-layer'){layer=Number(b.dataset.depth);renderer.layer=layer;renderer.groundKey='';chooseTab('depth');}else if(a==='descend')act(G.changeDepth(state,selected,layer));else if(a==='travel'){const r=act(G.travel(state,id,selected.filter(uid=>m.units.some(u=>u.id===uid&&G.TROOPS[u.type].naval))));if(r.ok){selected=G.units(state).filter(u=>!u.embarked).map(u=>u.id);layer=0;renderer.layer=0;renderer.map=G.currentMap(state);center();chooseTab('base');}}else if(a==='focus-exit'||a==='focus-faction'){const target=(a==='focus-exit'?m.exits:m.factions).find(t=>t.id===id);if(target){chooseTab('base');renderer.centerOn(target.x,target.y);}}else if(a==='create-route')act(G.establishRoute(state,routeTo,routeKind,routeResource,20));else if(a==='rail-route')act(G.railRoute(state,routeResource));else if(a==='export')await exportWorld();else if(a==='import')$('#import').click();else if(a==='confirm-import'){state=pendingImport;pendingImport=null;loadError=null;gameOverShown=false;selected=G.units(state).filter(u=>!u.embarked).slice(0,1).map(u=>u.id);layer=0;renderer.layer=0;renderer.map=G.currentMap(state);center();$('#modal').close();chooseTab('base');await save();toast('Mundo importado.');}else if(a==='reset-dialog')modal(modalHead('¿Fundar un mundo nuevo?')+'<p>La campaña de Horizontes de este dispositivo se reemplazará. Exporta una copia si quieres conservarla. La campaña clásica tiene un guardado separado.</p><div class="actions"><button data-action="export">Exportar antes</button><button class="primary" data-action="reset">Crear mundo nuevo</button><button data-action="close-modal">Cancelar</button></div>');else if(a==='reset'){state=G.createSurvival();loadError=null;gameOverShown=false;selected=G.units(state).map(u=>u.id);layer=0;renderer.layer=0;renderer.map=G.currentMap(state);center();$('#modal').close();chooseTab('base');await save();guide();}else if(a==='install'){if(installPrompt){await installPrompt.prompt();installPrompt=null;}else toast('Usa el menú del navegador para instalar la aplicación.');}
});
document.addEventListener('change',e=>{if(e.target.id==='recruit-species')recruitSpecies=e.target.value;if(e.target.id==='route-to')routeTo=e.target.value;if(e.target.id==='route-kind')routeKind=e.target.value;if(e.target.id==='route-resource')routeResource=e.target.value;if(e.target.id==='layer-range'){layer=Number(e.target.value);renderer.layer=layer;renderer.groundKey='';$('#layer-label').textContent=layer+' / 40';}});
$('#import').addEventListener('change',async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;if(file.size>64*1024*1024){toast('La copia supera el límite de 64 MB.');return;}try{pendingImport=G.deserialize(await file.text());modal(modalHead('Mundo preparado para importar.')+'<p>Mapa activo: '+esc(G.currentMap(pendingImport).name)+'. '+Object.keys(pendingImport.maps).length+' territorios visitados, era '+G.ERAS[pendingImport.era].name+'. Reemplazará la campaña actual de este dispositivo.</p><div class="actions"><button data-action="export">Exportar mundo actual</button><button class="primary" data-action="confirm-import">Importar este mundo</button><button data-action="close-modal">Cancelar</button></div>');}catch{pendingImport=null;toast('Copia incompatible o dañada. Las partidas antiguas se abren en Campaña clásica.');}});
function pick(px,py){const m=G.currentMap(state);return [...m.units].reverse().find(u=>u.hp>0&&!u.embarked&&u.depth===layer&&(()=>{const p=renderer.groundPoint(u.x,u.y),sc=renderer.scale*renderer.camera.zoom;return Math.abs(px-p.x)<22*sc&&py>p.y-52*sc&&py<p.y+9*sc;})());}
function orderAt(px,py,append=false){const m=G.currentMap(state),p=renderer.tileAt(px,py),point={x:p.x+.5,y:p.y+.5},target=[...(m.enemies||[]),...m.factions.filter(f=>f.hostile&&f.owner!=='player')].find(f=>Math.hypot(f.x-point.x,f.y-point.y)<2&&m.sight?.[Math.floor(f.y)*m.size+Math.floor(f.x)]);const node=G.resourceAt(m,p.x,p.y),civ=m.units.some(u=>selected.includes(u.id)&&G.TROOPS[u.type].civilian);return act(G.order(state,selected,target?'attack':node&&civ&&mode!=='attackMove'?'gather':mode==='attackMove'?'attackMove':'move',target?.x??point.x,target?.y??point.y,target?.id,append,formation));}
function tap(px,py,append=false){const m=G.currentMap(state),p=renderer.tileAt(px,py);hover=p;if(tool?.startsWith('road-')){roadPoints.push({x:p.x+.5,y:p.y+.5});const curved=tool==='road-curve';if(roadPoints.length===(curved?3:2)){const r=act(G.planRoad(state,roadPoints,roadGrade,curved,selected));if(r.ok){roadPoints=[];roadPreview=null;}else roadPoints.pop();}updateRoadPreview();return;}if(tool){if(G.STRUCTURES[tool]){const r=act(G.build(state,tool,p.x,p.y));if(r.ok)tool=null;}else if(tool==='dig')act(G.dig(state,selected,p.x,p.y,layer));else if(layer)act(G.placeBlock(state,selected,tool,p.x,p.y,layer));else act(G.infrastructure(state,tool,p.x,p.y));renderDock();return;}
 const u=pick(px,py);if(u){selected=append?[...new Set([...selected,u.id])]:[u.id];mode='select';render();return;}const building=renderer.hitSettlement(px,py)||m.buildings.find(b=>p.x>=b.x&&p.y>=b.y&&p.x<b.x+G.STRUCTURES[b.type].size&&p.y<b.y+G.STRUCTURES[b.type].size);if(building&&!['move','attackMove','gather'].includes(mode)){selected=[building.id];render();if(innerWidth<850)modal(upgradeView(state,building.id));return;}if(selected.some(id=>m.units.some(u=>u.id===id))){orderAt(px,py,append);return;}selected=[];renderSidebar();drawArt();}
function updateRoadPreview(extra=null){if(!tool?.startsWith('road-'))return;const curved=tool==='road-curve',points=[...roadPoints,...(extra?[extra]:[])];if(points.length===(curved?3:2))roadPreview=G.roadQuote(state,points,roadGrade,curved);else roadPreview=null;const label=$('#road-price');if(label)label.textContent=roadPreview?(roadPreview.ok?Object.entries(roadPreview.cost).map(([k,v])=>v+' '+G.STOCK_NAMES[k]).join(' · '):roadPreview.error):curved?'Marca inicio, control y final.':'Marca inicio y final, o arrastra el tramo.';}
const canvas=$('#game');let pointers=new Map(),start=null,last=null,pinch=null,dragged=false;
canvas.addEventListener('contextmenu',e=>e.preventDefault());canvas.addEventListener('pointerdown',e=>{if(tab!=='base')return;canvas.setPointerCapture(e.pointerId);const r=canvas.getBoundingClientRect(),p={x:e.clientX-r.left,y:e.clientY-r.top};pointers.set(e.pointerId,p);if(pointers.size===2){const[a,b]=[...pointers.values()];pinch={distance:Math.hypot(a.x-b.x,a.y-b.y),zoom:renderer.camera.zoom};start=null;box=null;return;}start={...p,button:e.button,road:tool?.startsWith('road-'),pan:!tool?.startsWith('road-')&&(e.button===1||e.altKey||mode==='pan'||e.pointerType==='touch'),shift:e.shiftKey};last=p;dragged=false;});
canvas.addEventListener('pointermove',e=>{const r=canvas.getBoundingClientRect(),p={x:e.clientX-r.left,y:e.clientY-r.top};hover=renderer.tileAt(p.x,p.y);if(tool?.startsWith('road-'))updateRoadPreview({x:hover.x+.5,y:hover.y+.5});if(!pointers.has(e.pointerId))return;pointers.set(e.pointerId,p);if(pointers.size===2&&pinch){const[a,b]=[...pointers.values()];renderer.camera.zoom=Math.max(.35,Math.min(2.5,pinch.zoom*Math.hypot(a.x-b.x,a.y-b.y)/Math.max(1,pinch.distance)));return;}if(!start)return;if(Math.hypot(p.x-start.x,p.y-start.y)>6)dragged=true;if(dragged&&start.road){if(tool==='road-straight'){const a=renderer.tileAt(start.x,start.y);roadPreview=G.roadQuote(state,[{x:a.x+.5,y:a.y+.5},{x:hover.x+.5,y:hover.y+.5}],roadGrade,false);}return;}if(dragged){if(start.pan){renderer.camera.x+=p.x-last.x;renderer.camera.y+=p.y-last.y;}else if(start.button!==2)box={x:start.x,y:start.y,w:p.x-start.x,h:p.y-start.y};}last=p;});
canvas.addEventListener('pointerup',e=>{pointers.delete(e.pointerId);if(pinch){if(!pointers.size)pinch=null;start=null;return;}const r=canvas.getBoundingClientRect(),px=e.clientX-r.left,py=e.clientY-r.top;if(start?.road&&dragged&&tool==='road-straight'){const a=renderer.tileAt(start.x,start.y),b=renderer.tileAt(px,py);act(G.planRoad(state,[{x:a.x+.5,y:a.y+.5},{x:b.x+.5,y:b.y+.5}],roadGrade,false,selected));roadPoints=[];roadPreview=null;start=null;return;}if(box){const x1=Math.min(box.x,box.x+box.w),x2=Math.max(box.x,box.x+box.w),y1=Math.min(box.y,box.y+box.h),y2=Math.max(box.y,box.y+box.h),ids=G.units(state).filter(u=>{const p=renderer.groundPoint(u.x,u.y);return u.hp>0&&!u.embarked&&u.depth===layer&&p.x>=x1&&p.x<=x2&&p.y>=y1&&p.y<=y2;}).map(u=>u.id);selected=[...new Set([...(e.shiftKey?selected:[]),...ids])];render();}else if(start&&!dragged){if(start.button===2)orderAt(px,py,e.shiftKey);else tap(px,py,e.shiftKey);}box=null;start=null;last=null;});
canvas.addEventListener('pointercancel',e=>{pointers.delete(e.pointerId);start=null;box=null;pinch=null;});canvas.addEventListener('wheel',e=>{e.preventDefault();const p=renderer.unproject(e.offsetX,e.offsetY);renderer.camera.zoom=Math.max(.35,Math.min(2.5,renderer.camera.zoom-e.deltaY*.001));const q=renderer.p(p.x,p.y);renderer.camera.x+=e.offsetX-q.x;renderer.camera.y+=e.offsetY-q.y;},{passive:false});
$('#minimap').addEventListener('pointerdown',e=>{const r=e.currentTarget.getBoundingClientRect(),m=G.currentMap(state),scale=m.miniSpan||256,center=m.miniCenter||{x:m.size/2,y:m.size/2};renderer.centerOn(center.x+((e.clientX-r.left)/r.width-.5)*scale,center.y+((e.clientY-r.top)/r.height-.5)*scale);});
function minimap(){const m=G.currentMap(state),canvas=$('#minimap'),c=canvas.getContext('2d'),w=canvas.width,h=canvas.height,image=c.createImageData(w,h),center=renderer.unproject(renderer.w*.51,renderer.h*.49),span=256;m.miniSpan=span;m.miniCenter=center;for(let y=0;y<h;y++)for(let x=0;x<w;x++){const xx=Math.floor(center.x+(x/w-.5)*span),yy=Math.floor(center.y+(y/h-.5)*span),known=xx>=0&&yy>=0&&xx<m.size&&yy<m.size&&m.fog[yy*m.size+xx],t=known?G.tile(m,xx,yy):null,color=!known?[24,45,55]:t.kind==='water'?[74,127,148]:t.kind==='mountain'?[154,169,159]:t.kind==='forest'?[81,120,83]:[147,166,112],i=(y*w+x)*4;image.data.set([...color,255],i);}c.putImageData(image,0,0);for(const u of m.units.filter(u=>u.hp>0&&!u.embarked)){c.fillStyle=selected.includes(u.id)?'#eff1bd':'#87d1d2';c.fillRect((u.x-center.x)/span*w+w/2-1,(u.y-center.y)/span*h+h/2-1,3,3);}for(const b of m.buildings){c.fillStyle='#e9c99c';c.fillRect((b.x-center.x)/span*w+w/2,(b.y-center.y)/span*h+h/2,3,3);}const corners=[[0,0],[renderer.w,0],[renderer.w,renderer.h],[0,renderer.h]].map(([x,y])=>renderer.unproject(x,y));c.strokeStyle='#e5ddb1';c.beginPath();corners.forEach((p,i)=>i?c.lineTo((p.x-center.x)/span*w+w/2,(p.y-center.y)/span*h+h/2):c.moveTo((p.x-center.x)/span*w+w/2,(p.y-center.y)/span*h+h/2));c.closePath();c.stroke();$('#map-status').textContent=m.size+' × '+m.size+' · '+(m.fog.count/m.size**2*100).toFixed(4)+'% explorado · Vista local';}
addEventListener('keydown',e=>{if(e.target.matches('input,textarea,select')||$('#modal').open)return;const key=e.key.toLowerCase();if(key==='escape'){tool=null;mode='select';chooseTab('base');}if(key==='a'){mode='attackMove';renderDock();}if(key==='m'){mode='move';renderDock();}if(key==='s')act(G.order(state,selected,'hold'));if(key==='g'){mode='gather';renderDock();}if(key===' '){e.preventDefault();center();}if(/^[1-9]$/.test(key)){e.preventDefault();if(e.ctrlKey)groups[key]=[...selected];else selected=(groups[key]||[]).filter(id=>G.units(state).some(u=>u.id===id));render();}});
new ResizeObserver(()=>renderer.resize()).observe($('#field'));addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;});addEventListener('pagehide',()=>{if(!loadError)emergencyMirror(G.serialize(state));save();});document.addEventListener('visibilitychange',()=>{if(document.hidden)save();lastFrame=performance.now();});
if('serviceWorker'in navigator&&!globalThis.Capacitor?.isNativePlatform?.()&&['https:','http:'].includes(location.protocol))navigator.serviceWorker.register('./sw.js').catch(()=>toast('No se pudo activar el modo sin conexión.'));
let lastFrame=performance.now(),lastUi=0,lastPaint=0,gameOverShown=false;
function frame(t){const dt=Math.min(.1,(t-lastFrame)/1000);lastFrame=t;if(!document.hidden&&!$('#modal').open){renderer.addShots(G.step(state,dt));if(state.gameOver&&!gameOverShown){gameOverShown=true;modal(modalHead('La última luz de Aurora.')+'<p>No quedan colonos ni campamentos donde reclutarlos. Las bajas son definitivas. Puedes importar una copia anterior o fundar un mundo nuevo.</p><div class="actions"><button data-action="import">Importar copia</button><button data-action="reset-dialog">Nueva campaña</button></div>');}if(t-lastUi>1100){renderResources();renderSidebar();if(tab!=='base'&&!document.activeElement.matches('select,input'))renderPanel();drawArt();minimap();lastUi=t;if(state.time-lastSave>10)save();}}if(t-lastPaint>32){renderer.draw(state,{selected,tool,hover,selectionBox:box,roadPreview});lastPaint=t;}requestAnimationFrame(frame);}
render();minimap();Promise.all([artReady,realismReady]).then(()=>{renderer.groundKey='';render();});if(loadError)modal(modalHead('La copia local necesita revisión.')+'<p>No se pudo leer el mundo guardado. Su copia se conserva y el guardado automático está detenido para no reemplazarla. Puedes importar una copia válida o elegir crear un mundo nuevo desde Ajustes.</p><div class="actions"><button data-action="import">Importar copia</button><button data-action="settings">Abrir ajustes</button></div>');else if(!state.tutorialSeen)guide();requestAnimationFrame(frame);
